INSERT INTO categories (name_ru) VALUES ('Дача и огород') ON CONFLICT (name_ru) DO NOTHING;
INSERT INTO categories (name_ru) VALUES ('Сельское хозяйство') ON CONFLICT (name_ru) DO NOTHING;
INSERT INTO genera (name_lat, name_ru, care_summary) VALUES ('Ficus', 'Фикус', 'Фикусы любят яркий рассеянный свет, постоянное место без сквозняков и умеренный полив после подсыхания верхнего слоя почвы. Листья периодически протирайте от пыли, зимой поливайте реже. Вид различается по листу: у каучуконосного листья крупные глянцевые, у Бенджамина мелкие заострённые, у лировидного крупные волнистые скрипкообразные.') ON CONFLICT (name_lat) DO UPDATE SET name_ru = EXCLUDED.name_ru, care_summary = EXCLUDED.care_summary;
INSERT INTO genera (name_lat, name_ru, care_summary) VALUES ('Aloe', 'Алоэ', 'Алоэ — суккуленты: яркий свет, редкий полив только после полного просыхания грунта, рыхлый дренированный субстрат и прохладная зимовка. Основная причина гибели — переувлажнение.') ON CONFLICT (name_lat) DO UPDATE SET name_ru = EXCLUDED.name_ru, care_summary = EXCLUDED.care_summary;
INSERT INTO genera (name_lat, name_ru, care_summary) VALUES ('Dracaena', 'Драцена', 'Драцены, включая сансевиерию, неприхотливы: рассеянный свет или полутень, умеренный полив после подсыхания верхнего слоя грунта (сансевиерию поливают заметно реже), защита от сквозняков и от застоя воды.') ON CONFLICT (name_lat) DO UPDATE SET name_ru = EXCLUDED.name_ru, care_summary = EXCLUDED.care_summary;
INSERT INTO genera (name_lat, name_ru, care_summary) VALUES ('Pelargonium', 'Пеларгония (герань)', 'Пеларгонии любят много света, умеренный полив без застоя воды, прохладную зимовку и весеннюю обрезку. Листья не опрыскивают.') ON CONFLICT (name_lat) DO UPDATE SET name_ru = EXCLUDED.name_ru, care_summary = EXCLUDED.care_summary;
INSERT INTO genera (name_lat, name_ru, care_summary) VALUES ('Solanum', 'Паслён', 'Паслёновые культуры (томат, картофель, баклажан) теплолюбивы: нужны солнце, регулярный полив под корень, подкормки и севооборот. Общая угроза — фитофтороз, поэтому не загущайте посадки и проветривайте теплицу.') ON CONFLICT (name_lat) DO UPDATE SET name_ru = EXCLUDED.name_ru, care_summary = EXCLUDED.care_summary;
INSERT INTO genera (name_lat, name_ru, care_summary) VALUES ('Allium', 'Лук', 'Луковые (лук, чеснок) предпочитают солнечное место и рыхлую плодородную почву, умеренный полив с прекращением за 2–4 недели до уборки. Соблюдайте севооборот.') ON CONFLICT (name_lat) DO UPDATE SET name_ru = EXCLUDED.name_ru, care_summary = EXCLUDED.care_summary;
INSERT INTO genera (name_lat, name_ru, care_summary) VALUES ('Prunus', 'Слива и вишня', 'Косточковые (вишня, слива) любят солнечное место, защищённое от ветра, нейтральную почву, полив в засуху и санитарную обрезку. Для урожая подбирайте опылители.') ON CONFLICT (name_lat) DO UPDATE SET name_ru = EXCLUDED.name_ru, care_summary = EXCLUDED.care_summary;
INSERT INTO genera (name_lat, name_ru, care_summary) VALUES ('Brassica', 'Капуста', 'Капустные (капуста, рапс) — прохладолюбивые культуры: солнце, влажная плодородная почва, обильный полив, защита от крестоцветной блошки и севооборот.') ON CONFLICT (name_lat) DO UPDATE SET name_ru = EXCLUDED.name_ru, care_summary = EXCLUDED.care_summary;
