INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Ficus_elastica', 'Ficus elastica', 'Фикус каучуконосный (эластика)', (SELECT genus_id FROM genera WHERE name_lat = 'Ficus'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Ficus_elastica'), 'Неприхотливое декоративно-лиственное растение с крупными глянцевыми листьями.', 'Яркий рассеянный свет, допустима лёгкая полутень.', 'Умеренно, когда верхний слой почвы подсохнет на 2–3 см; зимой реже.', '18–25 °C; зимой не ниже 12–15 °C.', 'С апреля по сентябрь раз в 2–3 недели удобрением для декоративно-лиственных.', 'Протирайте листья влажной тканью, не переставляйте без нужды. Млечный сок может раздражать кожу.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Ficus_benjamina', 'Ficus benjamina', 'Фикус Бенджамина', (SELECT genus_id FROM genera WHERE name_lat = 'Ficus'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Ficus_benjamina'), 'Деревце с мелкими глянцевыми листьями; чувствительно к смене места и сквознякам.', 'Яркий рассеянный свет без жёсткого прямого солнца.', 'Умеренно, после подсыхания верхнего слоя; не допускайте застоя воды.', '18–25 °C; зимой не ниже 15 °C.', 'С весны до осени раз в 2–3 недели.', 'Сбрасывает листья при сквозняках, перестановке и пересыхании кома.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Ficus_lyrata', 'Ficus lyrata', 'Фикус лировидный', (SELECT genus_id FROM genera WHERE name_lat = 'Ficus'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Ficus_lyrata'), 'Крупные волнистые листья скрипичной формы; требовательнее других фикусов.', 'Очень яркий рассеянный свет, лучше у южного или восточного окна.', 'Умеренно, давая почве подсохнуть сверху; не заливайте.', '18–24 °C, без сквозняков.', 'Весной и летом раз в 2 недели.', 'Не любит перемен места; регулярно протирайте листья, поддерживайте влажность воздуха.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Aloe_vera', 'Aloe vera', 'Алоэ вера', (SELECT genus_id FROM genera WHERE name_lat = 'Aloe'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Aloe_vera'), 'Суккулент с мясистыми листьями, часто держат в домашней аптечке.', 'Яркий свет, допустимо прямое солнце (приучать постепенно).', 'Редко: после полного просыхания грунта; зимой раз в месяц.', '20–28 °C летом; зимой 10–15 °C.', 'Весной и летом раз в месяц удобрением для кактусов и суккулентов.', 'Нужен дренаж и рыхлый грунт; от избытка влаги быстро гниёт корень.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Aloe_arborescens', 'Aloe arborescens', 'Алоэ древовидное (столетник)', (SELECT genus_id FROM genera WHERE name_lat = 'Aloe'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Aloe_arborescens'), 'Ветвистый суккулент, вырастающий в небольшое деревце.', 'Яркий свет, лучше южное или восточное окно.', 'Умеренно летом, скудно зимой; грунт должен просохнуть.', '18–25 °C; зимой 10–14 °C.', 'Раз в месяц весной и летом.', 'Летом полезно выносить на воздух; для здорового роста нужна прохладная зимовка.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Dracaena_trifasciata', 'Dracaena trifasciata', 'Сансевиерия (щучий хвост, тёщин язык)', (SELECT genus_id FROM genera WHERE name_lat = 'Dracaena'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Dracaena_trifasciata'), 'Очень выносливое растение с жёсткими вертикальными листьями.', 'От полутени до яркого света; пёстрые формы любят больше света.', 'Редко: летом раз в 1–2 недели, зимой раз в месяц; не лейте в розетку листьев.', '18–28 °C; не ниже 10 °C.', 'Раз в месяц весной и летом удобрением для суккулентов.', 'Главная причина гибели — переувлажнение; нужен лёгкий дренированный грунт.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Dracaena_fragrans', 'Dracaena fragrans', 'Драцена душистая', (SELECT genus_id FROM genera WHERE name_lat = 'Dracaena'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Dracaena_fragrans'), 'Пальмовидное растение с широкими арочными листьями.', 'Яркий рассеянный свет или полутень.', 'Умеренно, после подсыхания верхнего слоя; без застоя воды.', '18–25 °C; зимой не ниже 12 °C.', 'Раз в 2–3 недели с весны до осени.', 'Кончики листьев сохнут от сухого воздуха и жёсткой воды; опрыскивайте и поливайте отстоянной водой.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Chlorophytum_comosum', 'Chlorophytum comosum', 'Хлорофитум хохлатый', (SELECT genus_id FROM genera WHERE name_lat = 'Chlorophytum'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Chlorophytum_comosum'), 'Неприхотливое растение с полосатыми листьями и «детками» на длинных побегах.', 'Яркий рассеянный свет, переносит полутень.', 'Регулярно летом, умеренно зимой; запасает влагу в утолщённых корнях.', '18–25 °C; не ниже 10 °C.', 'Раз в 2–3 недели весной и летом.', 'Кончики листьев буреют от сухого воздуха и жёсткой воды; легко размножается детками.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Spathiphyllum_wallisii', 'Spathiphyllum wallisii', 'Спатифиллум («женское счастье»)', (SELECT genus_id FROM genera WHERE name_lat = 'Spathiphyllum'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Spathiphyllum_wallisii'), 'Цветёт белыми покрывалами-соцветиями, любит влагу.', 'Полутень или рассеянный свет; прямое солнце вредно.', 'Регулярно, грунт слегка влажный; при пересыхании листья вянут, но быстро оживают.', '20–25 °C; не ниже 16 °C.', 'Раз в 2 недели в период роста и цветения.', 'Опрыскивайте, используйте мягкую отстоянную воду. При нехватке света не цветёт.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Zamioculcas_zamiifolia', 'Zamioculcas zamiifolia', 'Замиокулькас («долларовое дерево»)', (SELECT genus_id FROM genera WHERE name_lat = 'Zamioculcas'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Zamioculcas_zamiifolia'), 'Очень выносливое растение, накапливающее воду в клубнях.', 'Рассеянный свет, переносит тень.', 'Редко: после полного просыхания грунта, примерно раз в 1–2 недели.', '18–26 °C; не ниже 12 °C.', 'Раз в месяц весной и летом.', 'Не заливайте: клубни и корни легко гниют. Сок ядовит, работайте в перчатках.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Monstera_deliciosa', 'Monstera deliciosa', 'Монстера деликатесная', (SELECT genus_id FROM genera WHERE name_lat = 'Monstera'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Monstera_deliciosa'), 'Лиана с крупными резными листьями.', 'Яркий рассеянный свет.', 'Умеренно, когда верхний слой подсохнет на 3–4 см.', '18–27 °C; не ниже 15 °C.', 'Раз в 2 недели весной и летом.', 'Нужна опора; воздушные корни не обрезайте, направляйте в грунт. Ядовита при поедании.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Epipremnum_aureum', 'Epipremnum aureum', 'Эпипремнум золотистый (потос)', (SELECT genus_id FROM genera WHERE name_lat = 'Epipremnum'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Epipremnum_aureum'), 'Неприхотливая лиана с пёстрыми сердцевидными листьями.', 'Рассеянный свет; в тени пёстрая окраска бледнеет.', 'Умеренно, после подсыхания верхнего слоя грунта.', '18–27 °C; не ниже 12 °C.', 'Раз в 2–3 недели весной и летом.', 'Хорош в подвесных кашпо и на опоре; прищипывайте для кустистости. Ядовит для животных.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Pelargonium_zonale', 'Pelargonium zonale', 'Пеларгония зональная (герань)', (SELECT genus_id FROM genera WHERE name_lat = 'Pelargonium'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Pelargonium_zonale'), 'Цветёт почти всё тёплое время года, листья с запахом и тёмным пояском.', 'Много света, допустимо прямое солнце.', 'Умеренно, после подсыхания верхнего слоя; без застоя воды.', '18–25 °C; зимой лучше 8–12 °C.', 'Раз в 2 недели удобрением для цветущих растений с калием.', 'Весной обрезайте и прищипывайте; листья не опрыскивайте.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Pelargonium_peltatum', 'Pelargonium peltatum', 'Пеларгония плющелистная (ампельная герань)', (SELECT genus_id FROM genera WHERE name_lat = 'Pelargonium'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Pelargonium_peltatum'), 'Пеларгония со свисающими побегами и плотными глянцевыми листьями.', 'Яркий свет, лучше без жаркого полуденного солнца.', 'Умеренно, без застоя воды.', '15–25 °C; зимой 8–12 °C.', 'Раз в 2 недели в период цветения.', 'Хороша в подвесных кашпо; удаляйте увядшие соцветия.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Crassula_ovata', 'Crassula ovata', 'Толстянка овальная (денежное дерево)', (SELECT genus_id FROM genera WHERE name_lat = 'Crassula'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Crassula_ovata'), 'Суккулент с мясистыми округлыми листьями.', 'Яркий свет, допустимо прямое солнце.', 'Редко: после просыхания грунта; зимой раз в месяц.', '18–25 °C; зимой 10–15 °C.', 'Раз в месяц весной и летом удобрением для суккулентов.', 'Прищипывайте для плотной кроны; в тени вытягивается.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Kalanchoe_blossfeldiana', 'Kalanchoe blossfeldiana', 'Каланхоэ Блоссфельда', (SELECT genus_id FROM genera WHERE name_lat = 'Kalanchoe'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Kalanchoe_blossfeldiana'), 'Суккулент с яркими соцветиями на зелёных мясистых листьях.', 'Яркий свет; для цветения нужен короткий световой день, около 10 часов.', 'Умеренно, зимой редко.', '18–25 °C; зимой 12–16 °C.', 'Раз в 2–3 недели во время роста.', 'После цветения срезайте соцветия; избегайте переувлажнения.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Hibiscus_rosa-sinensis', 'Hibiscus rosa-sinensis', 'Гибискус китайский (китайская роза)', (SELECT genus_id FROM genera WHERE name_lat = 'Hibiscus'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Hibiscus_rosa-sinensis'), 'Кустарник с крупными яркими цветами, живущими 1–2 дня.', 'Яркий свет, немного прямого солнца.', 'Обильно летом, умеренно зимой; не допускайте пересыхания.', '18–25 °C; зимой 12–16 °C.', 'Раз в 1–2 недели летом, предпочтительны фосфорно-калийные удобрения.', 'Сбрасывает бутоны при сквозняках и перестановке; формируйте обрезкой весной.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Phalaenopsis', 'Phalaenopsis', 'Фаленопсис (орхидея)', (SELECT genus_id FROM genera WHERE name_lat = 'Phalaenopsis'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'genus') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Phalaenopsis'), 'Самая распространённая комнатная орхидея; в продаже в основном гибриды.', 'Яркий рассеянный свет, без прямого солнца.', 'Погружением горшка на 15–30 минут, когда субстрат высох, а корни посеребрились; обычно раз в 5–10 дней.', '18–25 °C; для цветения нужен перепад день/ночь в 5–7 °C.', 'Раз в 2–3 недели специальным удобрением для орхидей в половинной дозе.', 'Прозрачный горшок и субстрат из коры; не заливайте точку роста, не срезайте зелёные воздушные корни.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Schlumbergera_truncata', 'Schlumbergera truncata', 'Шлюмбергера усечённая (декабрист)', (SELECT genus_id FROM genera WHERE name_lat = 'Schlumbergera'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Schlumbergera_truncata'), 'Эпифитный кактус с членистыми побегами, цветёт зимой.', 'Рассеянный свет, без жаркого прямого солнца.', 'Умеренно; перед бутонизацией полив немного сократите.', '18–24 °C; для закладки бутонов осенью 12–16 °C.', 'Раз в 2 недели весной и летом.', 'Не переставляйте и не поворачивайте горшок во время бутонизации, иначе растение сбросит бутоны.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Saintpaulia_ionantha', 'Saintpaulia ionantha', 'Сенполия (узамбарская фиалка)', (SELECT genus_id FROM genera WHERE name_lat = 'Saintpaulia'), (SELECT category_id FROM categories WHERE name_ru = 'Комнатные растения'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Saintpaulia_ionantha'), 'Небольшое цветущее растение с бархатистыми листьями; в ботанике сейчас относится к роду Streptocarpus.', 'Яркий рассеянный свет (восточное или западное окно).', 'Тёплой отстоянной водой через поддон или под корень, не допуская попадания воды на листья.', '18–24 °C.', 'Раз в 2 недели специальным удобрением для фиалок.', 'Не опрыскивайте, пересаживайте в небольшой горшок; капли воды на листьях на солнце оставляют ожоги.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Solanum_lycopersicum', 'Solanum lycopersicum', 'Томат (помидор)', (SELECT genus_id FROM genera WHERE name_lat = 'Solanum'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Solanum_lycopersicum'), 'Теплолюбивая овощная культура, одна из самых популярных на дачах.', 'Полное солнце, не менее 6–8 часов в день.', 'Редко, но обильно, под корень и без попадания воды на листья.', 'Оптимум 20–26 °C; рассаду высаживают после окончания заморозков.', 'Раз в 2–3 недели; в период плодоношения нужны калий и фосфор.', 'Пасынкуйте и подвязывайте высокие сорта; для профилактики фитофтороза не загущайте посадки и проветривайте теплицу.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Solanum_tuberosum', 'Solanum tuberosum', 'Картофель', (SELECT genus_id FROM genera WHERE name_lat = 'Solanum'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Solanum_tuberosum'), 'Главная клубневая культура огорода и полей.', 'Открытое солнечное место.', 'Умеренно; особенно важен полив в период бутонизации и цветения.', 'Сажают при прогреве почвы до 8–10 °C; клубни завязываются при 15–20 °C.', 'Органика и калий при посадке, окучивание 2 раза за сезон.', 'Меняйте место посадки каждые 3–4 года; следите за колорадским жуком и фитофторой.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Solanum_melongena', 'Solanum melongena', 'Баклажан', (SELECT genus_id FROM genera WHERE name_lat = 'Solanum'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Solanum_melongena'), 'Очень теплолюбивая овощная культура.', 'Полное солнце.', 'Тёплой водой, обильно и регулярно.', '22–28 °C; ниже 15 °C рост останавливается.', 'Раз в 2 недели комплексным удобрением.', 'Выращивают рассадой, лучше в теплице; ограничивайте число плодов на кусте.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Cucumis_sativus', 'Cucumis sativus', 'Огурец', (SELECT genus_id FROM genera WHERE name_lat = 'Cucumis'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Cucumis_sativus'), 'Влаголюбивая теплолюбивая культура, самая популярная на дачах.', 'Солнечное место или лёгкая полутень.', 'Часто и обильно тёплой водой, не допускайте пересыхания.', '22–28 °C; не переносит заморозков.', 'Раз в 2 недели: вначале азот, затем калий.', 'Подвязывайте на шпалеру; регулярный сбор плодов стимулирует новое плодоношение.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Cucurbita_pepo', 'Cucurbita pepo', 'Кабачок (тыква обыкновенная)', (SELECT genus_id FROM genera WHERE name_lat = 'Cucurbita'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Cucurbita_pepo'), 'Неприхотливая и высокоурожайная культура.', 'Солнечное место.', 'Обильно, под корень.', '18–25 °C; рассаду высаживают после заморозков.', 'Органика при посадке, подкормка раз в 2–3 недели.', 'Собирайте молодые плоды длиной 15–20 см; кусту нужно много места, не менее 70×70 см.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Capsicum_annuum', 'Capsicum annuum', 'Перец овощной', (SELECT genus_id FROM genera WHERE name_lat = 'Capsicum'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Capsicum_annuum'), 'Теплолюбивая культура, требует много света.', 'Полное солнце.', 'Регулярно тёплой водой, не пересушивайте.', '22–28 °C; ниже 13 °C рост замедляется.', 'Раз в 2 недели комплексным удобрением.', 'Не сажайте рядом сладкий и острый перец, они переопыляются; защитите от ветра.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Brassica_oleracea', 'Brassica oleracea', 'Капуста огородная', (SELECT genus_id FROM genera WHERE name_lat = 'Brassica'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Brassica_oleracea'), 'Прохладолюбивая овощная культура.', 'Солнечное место.', 'Обильно и регулярно; при нехватке влаги кочаны трескаются.', '15–20 °C; лёгкие заморозки переносит.', 'Вначале азот, затем сбалансированное удобрение.', 'Следите за капустной белянкой и крестоцветной блошкой; соблюдайте севооборот.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Daucus_carota', 'Daucus carota', 'Морковь', (SELECT genus_id FROM genera WHERE name_lat = 'Daucus'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Daucus_carota'), 'Корнеплод, один из базовых овощей огорода.', 'Солнечное место.', 'Равномерно; при неравномерном поливе корнеплоды трескаются.', 'Всходы при 5 °C и выше; рост при 15–20 °C.', 'Умеренно; свежий навоз вредит (корнеплоды ветвятся).', 'Нужна рыхлая песчаная почва; прореживайте всходы.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Allium_cepa', 'Allium cepa', 'Лук репчатый', (SELECT genus_id FROM genera WHERE name_lat = 'Allium'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Allium_cepa'), 'Основная луковичная культура огорода.', 'Солнечное место.', 'Умеренно; за 3–4 недели до уборки полив прекращают.', 'Рост при 15–25 °C.', 'Азот в начале роста, фосфор и калий в середине сезона.', 'Не сажайте на одном месте чаще чем раз в 3–4 года; убирают, когда перо полегло.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Allium_sativum', 'Allium sativum', 'Чеснок', (SELECT genus_id FROM genera WHERE name_lat = 'Allium'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Allium_sativum'), 'Озимый чеснок сажают осенью, яровой весной.', 'Солнечное место.', 'Умеренно во время роста; за 2–3 недели до уборки полив прекращают.', 'Озимый зимует в земле; рост при 12–20 °C.', 'Весной азот, в начале лета фосфор и калий.', 'Удаляйте стрелки у стрелкующихся сортов; убирают, когда нижние листья желтеют.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Anethum_graveolens', 'Anethum graveolens', 'Укроп', (SELECT genus_id FROM genera WHERE name_lat = 'Anethum'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Anethum_graveolens'), 'Быстрорастущая пряная зелень.', 'Солнечное место или лёгкая полутень.', 'Регулярно.', 'Всходы при 3–5 °C; хорошо растёт при 15–20 °C.', 'На плодородной почве обычно не нужна.', 'Сейте несколько раз за сезон с интервалом около 2 недель; не любит пересадку.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Fragaria_ananassa', 'Fragaria × ananassa', 'Клубника садовая', (SELECT genus_id FROM genera WHERE name_lat = 'Fragaria'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Fragaria_ananassa'), 'Самая популярная садовая ягода.', 'Солнечное место.', 'Регулярно, лучше капельно и без попадания воды на ягоды.', 'Зимует под снегом или укрытием; цветёт при 15 °C и выше.', 'Весной азот, после сбора ягод комплексное удобрение.', 'Мульчируйте соломой или агроволокном, убирайте лишние усы, обновляйте посадки каждые 3–4 года.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Rubus_idaeus', 'Rubus idaeus', 'Малина обыкновенная', (SELECT genus_id FROM genera WHERE name_lat = 'Rubus'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Rubus_idaeus'), 'Ягодный кустарник с двухлетними побегами.', 'Солнечное место или лёгкая полутень.', 'Регулярно, особенно при завязывании и наливе ягод.', 'Зимостойка; в северных регионах побеги пригибают.', 'Весной органика или азот, осенью фосфор и калий.', 'Ежегодно вырезайте отплодоносившие побеги, подвязывайте к шпалере.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Ribes_nigrum', 'Ribes nigrum', 'Смородина чёрная', (SELECT genus_id FROM genera WHERE name_lat = 'Ribes'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Ribes_nigrum'), 'Зимостойкий ягодный кустарник.', 'Солнечное место или лёгкая полутень.', 'Регулярно, особенно при наливе ягод.', 'Очень зимостойка.', 'Весной азот, осенью органика и калий.', 'Проводите омолаживающую обрезку; следите за почковым клещом и мучнистой росой.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Malus_domestica', 'Malus domestica', 'Яблоня домашняя', (SELECT genus_id FROM genera WHERE name_lat = 'Malus'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Malus_domestica'), 'Основная плодовая культура российских садов.', 'Солнечное место.', 'В засуху и при формировании плодов; взрослым деревьям редко, но обильно.', 'Зимостойкость зависит от сорта.', 'Весной азот, осенью фосфор, калий и органика.', 'Проводите весеннюю обрезку и побелку стволов; для опыления нужны разные сорта.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Prunus_cerasus', 'Prunus cerasus', 'Вишня обыкновенная', (SELECT genus_id FROM genera WHERE name_lat = 'Prunus'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Prunus_cerasus'), 'Зимостойкое плодовое дерево или куст; многие сорта самобесплодны.', 'Солнечное место, защищённое от ветра.', 'В засуху и при наливе ягод.', 'Зимостойкая культура.', 'Весной азот, осенью фосфор и калий.', 'Проводите санитарную обрезку; следите за монилиозом и коккомикозом.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Prunus_domestica', 'Prunus domestica', 'Слива домашняя', (SELECT genus_id FROM genera WHERE name_lat = 'Prunus'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Prunus_domestica'), 'Плодовое дерево, часто требует сортов-опылителей.', 'Солнечное место, защищённое от ветра.', 'Регулярно в засуху и при наливе плодов.', 'Зимостойкость зависит от сорта.', 'Весной азот, осенью фосфор и калий.', 'Прореживайте завязи, чтобы ветви не ломались под урожаем; обрезайте весной.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Rosa', 'Rosa', 'Роза садовая', (SELECT genus_id FROM genera WHERE name_lat = 'Rosa'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'genus') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Rosa'), 'Самые популярные цветы дачных участков; сорта и гибриды сильно различаются.', 'Не менее 6 часов солнца в день.', 'Редко, но обильно, под корень.', 'В большинстве регионов нужно укрывать на зиму.', 'Весной органика, летом комплексное удобрение до середины лета.', 'Обрезайте весной; для профилактики чёрной пятнистости и мучнистой росы обеспечьте проветривание.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Tulipa_gesneriana', 'Tulipa gesneriana', 'Тюльпан садовый', (SELECT genus_id FROM genera WHERE name_lat = 'Tulipa'), (SELECT category_id FROM categories WHERE name_ru = 'Дача и огород'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Tulipa_gesneriana'), 'Луковичное весеннее растение.', 'Солнечное место.', 'Умеренно во время роста и цветения.', 'Луковицы сажают в сентябре–октябре, когда почва остыла до 8–10 °C.', 'Весной азот и калий.', 'После цветения срезайте цветонос, листья оставляйте до пожелтения; раз в 2–3 года луковицы выкапывайте и сортируйте.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Triticum_aestivum', 'Triticum aestivum', 'Пшеница мягкая', (SELECT genus_id FROM genera WHERE name_lat = 'Triticum'), (SELECT category_id FROM categories WHERE name_ru = 'Сельское хозяйство'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Triticum_aestivum'), 'Главная зерновая культура России; бывает озимой и яровой.', 'Открытое поле.', 'Чаще богара; критичны периоды выхода в трубку и колошения.', 'Озимую сеют в конце лета — начале осени, яровую ранней весной; оптимум роста 15–22 °C.', 'Азот весной в подкормки, фосфор и калий при посеве.', 'Соблюдайте севооборот; защита от ржавчины, мучнистой росы и фузариоза.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Hordeum_vulgare', 'Hordeum vulgare', 'Ячмень обыкновенный', (SELECT genus_id FROM genera WHERE name_lat = 'Hordeum'), (SELECT category_id FROM categories WHERE name_ru = 'Сельское хозяйство'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Hordeum_vulgare'), 'Кормовая и пивоваренная зерновая культура, созревает раньше пшеницы.', 'Открытое поле.', 'Чаще богара; чувствителен к нехватке влаги при выходе в трубку и колошении.', 'Яровой сеют рано весной; рост при 15–20 °C.', 'Азот умеренно (избыток ведёт к полеганию), фосфор и калий при посеве.', 'Лучшие предшественники — пропашные и бобовые; защита от гельминтоспориозов и ржавчины.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Secale_cereale', 'Secale cereale', 'Рожь посевная', (SELECT genus_id FROM genera WHERE name_lat = 'Secale'), (SELECT category_id FROM categories WHERE name_ru = 'Сельское хозяйство'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Secale_cereale'), 'Самая зимостойкая зерновая культура, растёт на бедных и кислых почвах.', 'Открытое поле.', 'Чаще богара.', 'Озимую рожь сеют в конце лета — начале осени; хорошо зимует.', 'Умеренные дозы азота; фосфор и калий при посеве.', 'Растёт там, где пшеница не удаётся; следите за эрготом (спорыньёй) и полеганием.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Avena_sativa', 'Avena sativa', 'Овёс посевной', (SELECT genus_id FROM genera WHERE name_lat = 'Avena'), (SELECT category_id FROM categories WHERE name_ru = 'Сельское хозяйство'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Avena_sativa'), 'Влаголюбивая и холодостойкая культура для зерна и корма.', 'Открытое поле.', 'Требователен к влаге, особенно при выходе в трубку и метелкованию.', 'Сеют рано весной; оптимум 15–20 °C.', 'Азот умеренно, фосфор и калий при посеве.', 'Хороший фитосанитарный предшественник для других зерновых.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Zea_mays', 'Zea mays', 'Кукуруза', (SELECT genus_id FROM genera WHERE name_lat = 'Zea'), (SELECT category_id FROM categories WHERE name_ru = 'Сельское хозяйство'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Zea_mays'), 'Теплолюбивая культура, выращивается на зерно и силос.', 'Открытое поле, много света.', 'Особенно важна влага в период выметывания метёлки и налива зерна.', 'Сев при прогреве почвы до 10–12 °C; оптимум 20–25 °C.', 'Главный элемент — азот; также фосфор и цинк.', 'Широкорядный посев, борьба с сорняками на ранних этапах; защита от кукурузного мотылька.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Helianthus_annuus', 'Helianthus annuus', 'Подсолнечник', (SELECT genus_id FROM genera WHERE name_lat = 'Helianthus'), (SELECT category_id FROM categories WHERE name_ru = 'Сельское хозяйство'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Helianthus_annuus'), 'Главная масличная культура России, засухоустойчив.', 'Открытое поле, полное солнце.', 'Критичный период — от образования корзинки до цветения.', 'Сев при прогреве почвы до 8–10 °C; оптимум 20–25 °C.', 'Азот умеренно, фосфор, калий и бор.', 'Возвращайте на поле не чаще чем через 7–8 лет; болезни — белая гниль, ложная мучнистая роса, заразиха.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Glycine_max', 'Glycine max', 'Соя', (SELECT genus_id FROM genera WHERE name_lat = 'Glycine'), (SELECT category_id FROM categories WHERE name_ru = 'Сельское хозяйство'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Glycine_max'), 'Тепло- и влаголюбивая бобовая культура, обогащает почву азотом.', 'Открытое поле.', 'Критичны периоды цветения и налива бобов.', 'Сев при прогреве почвы до 12–14 °C; оптимум 20–25 °C.', 'При инокуляции семян клубеньковыми бактериями азот не нужен; вносят фосфор и калий.', 'Хороший предшественник для зерновых.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Brassica_napus', 'Brassica napus', 'Рапс', (SELECT genus_id FROM genera WHERE name_lat = 'Brassica'), (SELECT category_id FROM categories WHERE name_ru = 'Сельское хозяйство'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Brassica_napus'), 'Масличная культура, бывает озимой и яровой.', 'Открытое поле.', 'Требователен к влаге, особенно при бутонизации и цветении.', 'Яровой сеют очень рано, озимый в августе; оптимум 15–20 °C.', 'Высокая потребность в азоте, сере и боре.', 'Возвращайте на поле не ранее чем через 4 года; защита от крестоцветной блошки и рапсового цветоеда.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Beta_vulgaris', 'Beta vulgaris', 'Свёкла (сахарная, столовая, кормовая)', (SELECT genus_id FROM genera WHERE name_lat = 'Beta'), (SELECT category_id FROM categories WHERE name_ru = 'Сельское хозяйство'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Beta_vulgaris'), 'Двулетнее корнеплодное растение, из сахарной свёклы получают сахар.', 'Солнечное место.', 'Равномерно; при засухе падает сахаристость.', 'Сев при прогреве почвы до 5–7 °C; оптимум 18–22 °C.', 'Калий и бор; азот умеренно.', 'Нужна рыхлая плодородная почва с нейтральной реакцией; прореживайте всходы.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Fagopyrum_esculentum', 'Fagopyrum esculentum', 'Гречиха посевная', (SELECT genus_id FROM genera WHERE name_lat = 'Fagopyrum'), (SELECT category_id FROM categories WHERE name_ru = 'Сельское хозяйство'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Fagopyrum_esculentum'), 'Теплолюбивая крупяная и медоносная культура.', 'Открытое поле.', 'Чувствительна к засухе в период цветения.', 'Сев при 14–16 °C после окончания заморозков, которые губят всходы.', 'Умеренные дозы азота; растёт на бедных почвах.', 'Размещайте вблизи пасек: гречиха хороший медонос.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
INSERT INTO plants (class_id, name_lat, name_ru, genus_id, category_id, taxon_rank) VALUES ('Pisum_sativum', 'Pisum sativum', 'Горох посевной', (SELECT genus_id FROM genera WHERE name_lat = 'Pisum'), (SELECT category_id FROM categories WHERE name_ru = 'Сельское хозяйство'), 'species') ON CONFLICT (class_id) DO UPDATE SET name_lat = EXCLUDED.name_lat, name_ru = EXCLUDED.name_ru, genus_id = EXCLUDED.genus_id, category_id = EXCLUDED.category_id, taxon_rank = EXCLUDED.taxon_rank;
INSERT INTO plant_care (plant_id, summary, light, watering, temperature, feeding, tips) VALUES ((SELECT plant_id FROM plants WHERE class_id = 'Pisum_sativum'), 'Холодостойкая бобовая культура: зерновая и овощная.', 'Открытое поле или солнечная грядка.', 'Требователен к влаге при цветении и наливе бобов.', 'Сеют очень рано, при 4–6 °C; оптимум 15–20 °C.', 'Азот не нужен, вносят фосфор и калий.', 'Высокие сорта подвязывают к опоре; возвращать на то же место стоит не ранее чем через 4–5 лет.') ON CONFLICT (plant_id) DO UPDATE SET summary = EXCLUDED.summary, light = EXCLUDED.light, watering = EXCLUDED.watering, temperature = EXCLUDED.temperature, feeding = EXCLUDED.feeding, tips = EXCLUDED.tips;
